static const struct mox_iss_get_forward_rule mox_iss_get_forward_rules[] =
{
    { mox_col_ifadminstatus,      MOX_ISS_FWD_OIDLEN(mox_col_ifadminstatus),
      mox_probe_ifindex,          MOX_ISS_FWD_OIDLEN(mox_probe_ifindex)      },
