      mox_probe_ifname,           MOX_ISS_FWD_OIDLEN(mox_probe_ifname)       },
    { mox_col_ifpromiscuousmode,  MOX_ISS_FWD_OIDLEN(mox_col_ifpromiscuousmode),
      mox_probe_ifname,           MOX_ISS_FWD_OIDLEN(mox_probe_ifname)       },
    { mox_col_ifalias,            MOX_ISS_FWD_OIDLEN(mox_col_ifalias),
      mox_probe_ifname,           MOX_ISS_FWD_OIDLEN(mox_probe_ifname)       },
};

static const struct mox_iss_get_forward_rule *
mox_snmp_entry_iss_get_forward_rule (struct ies_auto_mibs_entry *entry)
{
    size_t r;
    int    i;
    for ( r = 0;
          r < sizeof(mox_iss_get_forward_rules)/sizeof(mox_iss_get_forward_rules[0]);
          r++ )
    {
        const struct mox_iss_get_forward_rule *rule = &mox_iss_get_forward_rules[r];
        if ( entry->oid_len != rule->col_oid_len )
        {
            continue;
        }
        for ( i = 0; i < entry->oid_len; i++ )
        {
            if ( (oid) entry->oid_list[i] != rule->col_oid[i] )
            {
                break;
            }
        }
        if ( i == entry->oid_len )
        {
            return rule;
        }
    }
    return NULL;
}

/* Forward a single GET/GETNEXT request to the ISS AgentX subagent, bypassing
 * the slow local ies_uri_handle path. agentx_master_handler marks the request
 * delegated and sends it async; net-snmp fills the value when ISS replies.
 * Returns 0 if handed to ISS, -1 if ISS is not registered (caller falls back). */
static int
mox_snmp_forward_get_to_iss (const struct mox_iss_get_forward_rule *rule,
                             netsnmp_agent_request_info *reqinfo,
                             netsnmp_request_info       *request)
{
    netsnmp_subtree      *iss_sub;
    netsnmp_request_info *saved_next;

    iss_sub = netsnmp_subtree_find(rule->probe_oid, rule->probe_oid_len,
                                   NULL, NULL);
    if ( iss_sub == NULL || iss_sub->reginfo == NULL ||
         iss_sub->reginfo->handler == NULL )
    {
        return -1;                      /* ISS AgentX subagent not connected */
    }

    /* Forward only THIS request; detach siblings so netsnmp_call_handlers does
     * not pull the rest of the chain (this handler is invoked per request). */
    saved_next    = request->next;
    request->next = NULL;
    (void) netsnmp_call_handlers(iss_sub->reginfo, reqinfo, request);
    request->next = saved_next;

    return 0;
}

